const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define South Los Angeles area
  const southLA = ee.Geometry.Point([-118.25, 33.95]).buffer(10000); // 10km radius

  // Function to mask poor quality pixels
  function maskQuality(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.75);
    return image.updateMask(mask);
  }

  // Get NO2 data for each period
  const no2_2018 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate('2018-10-01', '2018-10-24')
    .filterBounds(southLA)
    .map(maskQuality)
    .select('tropospheric_NO2_column_number_density');

  const no2_2019 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate('2019-10-01', '2019-10-24')
    .filterBounds(southLA)
    .map(maskQuality)
    .select('tropospheric_NO2_column_number_density');

  const no2_2021 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate('2021-10-01', '2021-10-24')
    .filterBounds(southLA)
    .map(maskQuality)
    .select('tropospheric_NO2_column_number_density');

  // Check collection sizes
  const size_2018 = no2_2018.size().getInfo();
  const size_2019 = no2_2019.size().getInfo();
  const size_2021 = no2_2021.size().getInfo();

  console.log(`Images: 2018=${size_2018}, 2019=${size_2019}, 2021=${size_2021}`);

  if (size_2018 === 0 || size_2019 === 0 || size_2021 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Calculate mean NO2 for each period
  const mean_2018 = no2_2018.mean();
  const mean_2019 = no2_2019.mean();
  const mean_2021 = no2_2021.mean();

  // Get statistics
  const stats_2018 = mean_2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: southLA,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats_2019 = mean_2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: southLA,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats_2021 = mean_2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: southLA,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const val_2018 = stats_2018['tropospheric_NO2_column_number_density_mean'];
  const count_2018 = stats_2018['tropospheric_NO2_column_number_density_count'];
  const val_2019 = stats_2019['tropospheric_NO2_column_number_density_mean'];
  const count_2019 = stats_2019['tropospheric_NO2_column_number_density_count'];
  const val_2021 = stats_2021['tropospheric_NO2_column_number_density_mean'];
  const count_2021 = stats_2021['tropospheric_NO2_column_number_density_count'];

  console.log(`2018: Mean=${val_2018}, Pixels=${count_2018}`);
  console.log(`2019: Mean=${val_2019}, Pixels=${count_2019}`);
  console.log(`2021: Mean=${val_2021}, Pixels=${count_2021}`);

  // Check for no valid pixels
  if (count_2018 === 0 || count_2019 === 0 || count_2021 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for invalid values
  if (val_2018 === null || val_2019 === null || val_2021 === null ||
      isNaN(val_2018) || isNaN(val_2019) || isNaN(val_2021) ||
      val_2018 < 0 || val_2019 < 0 || val_2021 < 0) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare: 2021 should be lower than BOTH 2018 and 2019
  if (val_2021 < val_2018 && val_2021 < val_2019) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
